  /** helper function to check RecoverySupervisor_material_continuity_process_recovery_supervisor's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param gate_to_demand method that will be called with the value of the outgoing data
   *        port 'gate_to_demand'.
   * @param gate_to_supply method that will be called with the value of the outgoing data
   *        port 'gate_to_supply'.
   * @param gate_to_urgent method that will be called with the value of the outgoing data
   *        port 'gate_to_urgent'.
   * @param gate_to_routine method that will be called with the value of the outgoing data
   *        port 'gate_to_routine'.
   * @param gate_to_replenishment method that will be called with the value of the outgoing data
   *        port 'gate_to_replenishment'.
   * @param emergency_state method that will be called with the value of the outgoing data
   *        port 'emergency_state'.
   * @param recovery_state method that will be called with the value of the outgoing data
   *        port 'recovery_state'.
   */
  def check_concrete_output(gate_to_demand: Factory_Material_Continuity_Coordinator.RecoveryGate.Type => B,
                            gate_to_supply: Factory_Material_Continuity_Coordinator.RecoveryGate.Type => B,
                            gate_to_urgent: Factory_Material_Continuity_Coordinator.RecoveryGate.Type => B,
                            gate_to_routine: Factory_Material_Continuity_Coordinator.RecoveryGate.Type => B,
                            gate_to_replenishment: Factory_Material_Continuity_Coordinator.RecoveryGate.Type => B,
                            emergency_state: Factory_Material_Continuity_Coordinator.EmergencyState.Type => B,
                            recovery_state: Factory_Material_Continuity_Coordinator.RecoveryState.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val gate_to_demandValue: Factory_Material_Continuity_Coordinator.RecoveryGate.Type = get_gate_to_demand().get
    if(!gate_to_demand(gate_to_demandValue)) {
      testFailures = testFailures :+ st"'gate_to_demand' did not match expected: value of the outgoing data port is ${gate_to_demandValue}"
    }
    val gate_to_supplyValue: Factory_Material_Continuity_Coordinator.RecoveryGate.Type = get_gate_to_supply().get
    if(!gate_to_supply(gate_to_supplyValue)) {
      testFailures = testFailures :+ st"'gate_to_supply' did not match expected: value of the outgoing data port is ${gate_to_supplyValue}"
    }
    val gate_to_urgentValue: Factory_Material_Continuity_Coordinator.RecoveryGate.Type = get_gate_to_urgent().get
    if(!gate_to_urgent(gate_to_urgentValue)) {
      testFailures = testFailures :+ st"'gate_to_urgent' did not match expected: value of the outgoing data port is ${gate_to_urgentValue}"
    }
    val gate_to_routineValue: Factory_Material_Continuity_Coordinator.RecoveryGate.Type = get_gate_to_routine().get
    if(!gate_to_routine(gate_to_routineValue)) {
      testFailures = testFailures :+ st"'gate_to_routine' did not match expected: value of the outgoing data port is ${gate_to_routineValue}"
    }
    val gate_to_replenishmentValue: Factory_Material_Continuity_Coordinator.RecoveryGate.Type = get_gate_to_replenishment().get
    if(!gate_to_replenishment(gate_to_replenishmentValue)) {
      testFailures = testFailures :+ st"'gate_to_replenishment' did not match expected: value of the outgoing data port is ${gate_to_replenishmentValue}"
    }
    val emergency_stateValue: Factory_Material_Continuity_Coordinator.EmergencyState.Type = get_emergency_state().get
    if(!emergency_state(emergency_stateValue)) {
      testFailures = testFailures :+ st"'emergency_state' did not match expected: value of the outgoing data port is ${emergency_stateValue}"
    }
    val recovery_stateValue: Factory_Material_Continuity_Coordinator.RecoveryState.Type = get_recovery_state().get
    if(!recovery_state(recovery_stateValue)) {
      testFailures = testFailures :+ st"'recovery_state' did not match expected: value of the outgoing data port is ${recovery_stateValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


